export type RelationshipActingState = {
  intimacyStage: 0 | 1 | 2 | 3 | 4 | 5;
  friendship: number;
  trust: number;
  playfulness: number;
  affection: number;
  romance: number;
  relationshipStatus?: "none" | "romantic_partner";
};

function clamp(value: number) {
